      return "<li>" + esc(m.label || m.kind) + ": " + esc(amount) + " · " + esc(m.method || "manual") + (m.retrieved ? " · " + esc(m.retrieved) : "") + (m.source ? " · " + esc(m.source) : "") + " <button type=\"button\" class=\"bh-linkbtn\" data-man-del=\"" + i + "\">Remove</button></li>";
